package com.reelsmaker.app;
import android.content.Context;import java.io.*;import java.util.*;import java.util.zip.*;
final class FacebookQ {private FacebookQ(){} static File dir(Context c){File d=new File(c.getFilesDir(),"facebook");if(!d.exists())d.mkdirs();return d;}static int extract(Context c,File zip)throws IOException{File d=dir(c);File[] old=d.listFiles();if(old!=null)for(File f:old)f.delete();int n=0;try(ZipInputStream z=new ZipInputStream(new FileInputStream(zip))){ZipEntry e;while((e=z.getNextEntry())!=null){if(e.isDirectory()||!e.getName().toLowerCase().endsWith(".mp4"))continue;String base=e.getName().substring(e.getName().lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._-]","_");File o=new File(d,String.format("%03d_%s",++n,base));try(OutputStream out=new FileOutputStream(o)){byte[] b=new byte[65536];int r;while((r=z.read(b))>0)out.write(b,0,r);}}}return n;}static List<File> list(Context c){File[] f=dir(c).listFiles((d,n)->n.endsWith(".mp4"));if(f==null)return new ArrayList<>();Arrays.sort(f);return new ArrayList<>(Arrays.asList(f));}}
